import re,os
def slug(h): 
    h=h.strip().lower(); h=re.sub(r'[^\w\- ]','',h); return h.replace(' ','-')
files=["docs/plans/v1.md","docs/product/milestones.md","docs/components/verification/README.md","docs/components/workspace/README.md","docs/components/agents/README.md","docs/components/escalation/README.md","docs/components/engine/README.md","docs/components/tui/README.md","docs/components/memory/README.md","docs/components/telemetry/README.md"]
for f in files:
    for m in re.finditer(r'\]\(([^)#]*)(#[^)]*)?\)', open(f).read()):
        path,anchor=m.group(1),m.group(2)
        if path.startswith('http'): continue
        target=os.path.normpath(os.path.join(os.path.dirname(f),path)) if path else f
        if not os.path.exists(target): print(f,"missing",path); continue
        if anchor and target.endswith('.md'):
            heads={slug(h) for h in re.findall(r'^#+ (.*)$',open(target).read(),re.M)}
            if anchor[1:] not in heads: print(f,"bad anchor",path+anchor)
EOF
